NAME = 'ACV: A Conservative Version'
BOOK = 'II Corinthians'

CHAPTERS = {
    1: {
        1: 'Pavel, apostol Kristusa Jezusa po volji Božji, in Timotej, brat, cerkvi Božji, ki je v Korintu, z vsemi svetimi, ki bivajo po vsej Ahaji:',
        2: 'Milost vam in mir od Boga Očeta našega in Gospoda Jezusa Kristusa!',
        3: 'Hvaljen bodi Bog in Oče Gospoda našega Jezusa Kristusa, Oče usmiljenosti in Bog vsake tolažbe,',
        4: 'ki nas tolaži v vsaki stiski, da moremo i mi tolažiti tiste, ki so v kakršnikoli stiski s to tolažbo, s katero nas same tolaži Bog.',
        5: 'Kajti kakor je obilno trpljenje Kristusovo pri nas, tako je po Kristusu obilna tolažba naša.',
        6: 'Če smo pa stiskani, je to za vašo tolažbo in rešitev; če pa uživamo tolažbo, je to za vašo tolažbo, ki naj vas podpira v prenašanju istega trpljenja, ki ga tudi mi trpimo.',
        7: 'In upanje naše je trdno za vas, ker vemo, da kakor ste deležniki trpljenja, tako ste tudi tolažbe.',
        8: 'Kajti nočemo, da bi ne vedeli, bratje, za stisko našo, ki se nam je dogodila v Aziji, da smo bili hudo preobteženi, nad svojo moč, tako da smo obupali tudi nad življenjem;',
        9: 'da, sami v sebi smo izrekli smrtno obsodbo, – naj bi ne stavili upanja svojega na sebi, ampak na Bogu, ki obuja mrtve;',
        10: 'ki nas je take smrti otel in otimlje, v katerega upamo, da bo še dalje otimal;',
        11: 'če pripomagate tudi vi nam z molitvijo, da bi se za dar, ki nam je dodeljen po molitvah mnogih, mnogi zahvaljevali zaradi nas.',
        12: 'Kajti hvala naša je ta: pričevanje vesti naše, da smo živeli v svetosti in čistosti Božji, ne v meseni modrosti, temuč v milosti Božji na svetu, posebno pa pri vas.',
        13: 'Kajti nič drugega vam ne pišemo, nego kar berete in kar morate tudi priznati; upam pa, da boste to do konca priznavali,',
        14: 'kakor ste tudi priznali nas, vsaj nekoliko, da smo hvala vaša, kakor tudi vi naša v dan Gospoda našega Jezusa.',
        15: 'In s tem zaupanjem sem hotel k vam priti poprej, da bi prejeli dvojno dobroto,',
        16: 'in od vas potovati v Macedonijo in zopet iz Macedonije priti k vam in od vas spremljen biti v Judejo.',
        17: 'Ko sem torej to hotel, sem li lahkomiselno ravnal? ali kar sklepam, sklepam po mesu, da bi bilo pri meni hkratu ‚da, da‘in ‚ne, ne‘?',
        18: 'Ali zvest je Bog, da beseda naša do vas ni bila ‚da‘in ‚ne‘.',
        19: 'Kajti Božji Sin Jezus Kristus, ki smo ga med vami oznanili jaz in Silvan in Timotej, ni bil ‚da‘in ‚ne‘, temuč v njem je bilo ‚da‘.',
        20: 'Zakaj kolikorkoli je obljub Božjih, v njem so ‚da‘, zato tudi po njem ‚Amen‘Bogu na slavo po nas.',
        21: 'Ta pa, ki nas utrjuje z vami vred v Kristusa in nas je pomazilil, je Bog,',
        22: 'ki nas je tudi zapečatil in dal zastavo Duha v srca naša.',
        23: 'A jaz kličem za pričo Boga na svojo dušo, da iz prizanašanja do vas še nisem prišel v Korint.',
        24: 'Ne da gospodujemo v veri vaši, temuč sodelavci smo za radost vašo; kajti z vero stojite.',
    },
    2: {
        1: 'Sklenil sem pa v sebi to, da zopet ne pridem z žalostjo k vam.',
        2: 'Kajti če jaz žalostim vas, kdo je, ki bi me razveselil, če ne ta, ki sem ga jaz užalostil?',
        3: 'In napisal sem vam prav to, da ne bi žalosti imel, ko pridem, s temi, nad katerimi bi se imel radovati; nadejajoč se za vas vse, da je moja radost vseh vas radost.',
        4: 'Kajti z veliko stisko in srčno težavo sem vam pisal, z mnogimi solzami, ne da se žalostite, marveč da spoznate ljubezen, ki je imam obilo do vas.',
        5: 'Če je pa kdo povzročil žalost, ni mene užalostil, temuč nekoliko (da ga preveč ne obtežim) vse vas.',
        6: 'Dosti je takemu ta kazen, ki ga je zadela od večine:',
        7: 'nasproti zdaj storite bolje, da mu odpustite in ga potolažite, da bi prevelika žalost morda ne pogoltnila takega.',
        8: 'Zato vas prosim, da potrdite ljubezen do njega.',
        9: 'Kajti zato sem tudi pisal, da vas preizkusim in spoznam, ste li v vsem poslušni.',
        10: 'Komur pa kaj odpustite, njemu tudi jaz; saj tudi kar sem jaz odpustil, če sem kaj odpustil, za voljo vas sem to storil pred obličjem Kristusovim,',
        11: 'da bi nas ne ukanil satan; kajti niso nam njegove misli neznane.',
        12: 'A ko sem prišel v Troado zavoljo evangelija Kristusovega in so mi bila vrata odprta v Gospodu,',
        13: 'nisem imel miru v duhu svojem, ker nisem našel Tita, brata svojega; temuč sem vzel slovo od njih in odšel v Macedonijo.',
        14: 'Ali hvala Bogu, ki nam vsekdar zmago daje v Kristusu in vonjavo spoznanja svojega razodeva po nas na vsakem mestu.',
        15: 'Kajti Kristusova prijetna dišava smo Bogu v teh, ki se zveličujejo, in v tistih, ki gredo v pogubo;',
        16: 'enim vonjava iz smrti za smrt, a drugim vonjava iz življenja za življenje. In kdo je zmožen za to?',
        17: 'Kajti nismo kakor mnogi, ki pokvarjajo besedo Božjo, temuč kakor iz čistote, kakor iz Boga, vpričo Boga govorimo v Kristusu.',
    },
    3: {
        1: 'Začenjamo li zopet sami sebe priporočati? ali potrebujemo li, kakor nekateri, priporočilnih listov do vas ali od vas?',
        2: 'List nas ste vi, napisan v srcih naših, ki ga poznajo in bero vsi ljudje,',
        3: 'ker se kažete, da ste list Kristusov, napravljen po naši službi, pisan ne s črnilom, ampak z Duhom Boga živega, ne na kamenitih pločah, ampak na mesenih pločah srca.',
        4: 'Tako zaupanje pa imamo po Kristusu do Boga:',
        5: 'Ne da bi bili zmožni, sami po sebi misliti kaj kakor sami iz sebe, temuč naša zmožnost je od Boga,',
        6: 'ki nas je storil tudi zmožne, da smo služabniki nove zaveze, ne črke, ampak Duha; kajti črka ubija, a Duh oživlja.',
        7: 'Če je pa služba smrti, v črkah in vrezana v kamene, bila polna slave, tako da niso mogli pogledati sinovi Izraelovi v obličje Mojzesovo zavoljo slave obličja njegovega, ki pa je bila minljiva:',
        8: 'kako naj bi ne bila veliko bolj polna slave služba Duha?',
        9: 'Zakaj ako je bila služba obsojanja slavna, veliko bolj je obila v slavi služba pravičnosti;',
        10: 'saj proti tej preveliki slavi nove zaveze, kakor da bi ne bila oslavljena stara zaveza, ki je pač bila oslavljena.',
        11: 'če je v slavi, kar je minljivo, veliko bolj je v slavi, kar je trajno.',
        12: 'Ker imamo torej toliko upanje, govorimo z veliko prostosrčnostjo',
        13: 'in ne delamo kakor Mojzes, ki si je deval zagrinjalo na obličje, da ne bi videli sinovi Izraelovi konca temu, kar je minljivo.',
        14: 'Ali njih misli so odrevenele. Kajti prav do današnjega dne ostaja isto zagrinjalo pri branju stare zaveze neodgrnjeno, ker se le v Kristusu odpravlja.',
        15: 'A do danes, kadarkoli se čita Mojzes, leži zagrinjalo na njih srcih.',
        16: 'Kadar se pa zgodi izpreobrnjenje v Gospodu, se sname zagrinjalo.',
        17: 'Gospod pa je Duh; kjer pa je Duh Gospodov, tam je svoboda.',
        18: 'A mi vsi, ki z odkritim obličjem gledamo kot v zrcalu slavo Gospodovo, se premenjujemo v isto podobo od slave v slavo, kakor od Gospodovega Duha.',
    },
    4: {
        1: 'Zatorej, ker opravljamo to službo, kakor smo dobili usmiljenje, ne izgubljamo srca;',
        2: 'ampak odrekli smo se skrivnim delom sramu ter ne ravnamo z zvijačami, tudi ne preobračamo besede Božje, marveč se z razodevanjem resnice priporočamo vesti vseh ljudi vpričo Boga.',
        3: 'Če je pa tudi zakrit evangelij naš, zakrit je tistim, ki gredo v pogubo,',
        4: 'ki jim je bog tega sveta nevernim oslepil misli, da jim ne zasveti svetlost evangelija slave Kristusa, ki je podoba Božja.',
        5: 'Kajti ne oznanjujemo sebe, temuč Kristusa Jezusa, da je Gospod, mi pa vaši služabniki zaradi Jezusa.',
        6: 'Ker Bog, ki je rekel: „Iz teme naj zasveti luč“, on je, ki je zasvetil v srcih naših, da dodeli svetlo spoznanje slave Božje v obličju Kristusovem.',
        7: 'Imamo pa ta zaklad v lončenih posodah, da bi bila preobilnost moči iz Boga in ne iz nas.',
        8: 'Od vseh strani nas stiskajo, ali nismo na tesnem; v zadregah smo, ali ne obupujemo;',
        9: 'preganjajo nas, ali nismo zapuščeni; pobijajo nas, ali ne ginemo;',
        10: 'vsekdar nosimo umiranje Jezusovo s seboj na telesu, da bi se tudi življenje Jezusovo pokazalo na našem telesu.',
        11: 'Kajti vedno smo mi, ki živimo, izročani na smrt zavoljo Jezusa, da bi se tudi življenje Jezusovo pokazalo na smrtnem mesu našem.',
        12: 'Tako smrt deluje v nas, a življenje v vas.',
        13: 'A imajoč istega duha vere po tem, kar je pisano: „Veroval sem, zato sem govoril“, tudi mi verujemo, zato tudi govorimo;',
        14: 'vedoč, da kateri je obudil Gospoda Jezusa, obudi tudi nas z Jezusom in postavi pred seboj z vami vred.',
        15: 'Vse je namreč za voljo vas, da bi milost, pomnožena po mnogih prejemalcih, povečala zahvalo v slavo Božjo.',
        16: 'Zato ne izgubljamo srca; ali čeprav se zunanji naš človek pokončuje, pa se notranji obnavlja od dne do dne.',
        17: 'Kajti sedanja kratka in lahka stiska naša nam napravlja nad vse obilno večno množino slave,',
        18: 'ko ne gledamo na to, kar se vidi, marveč na to, kar se ne vidi; zakaj to, kar se vidi, je začasno, a kar se ne vidi, je večno.',
    },
    5: {
        1: 'Vemo namreč, če razpade zemeljska hiša našega prebivanja, da imamo prebivališče od Boga, hišo, ne z rokami napravljeno, večno, v nebesih.',
        2: 'Kajti v tem tudi zdihujemo, želeč, povrhu se obleči v prebivališče svoje, ki je iz nebes;',
        3: 'če se le pokaže, da smo tudi oblečeni, ne goli.',
        4: 'Kajti kateri smo v tem šatoru, zdihujemo obteženi, ker se ne želimo sleči, ampak po vrhu se obleči, da življenje pogoltne to, kar je smrtnega.',
        5: 'Kateri nas je pa ravno za to pripravil, je Bog, ki nam je tudi dal zastavo Duha.',
        6: 'Dobre volje smo torej vsekdar in vemo, dokler stanujemo v telesu, potujemo na tujem daleč od Gospoda,',
        7: '(zakaj po veri živimo, ne po tem, kar gledamo);',
        8: 'dobre volje smo pa in želimo rajši preseliti se iz telesa in biti doma pri Gospodu.',
        9: 'Zato si tudi prizadevamo, bodisi da stanujemo v telesu ali da se selimo, da smo njemu po volji.',
        10: 'Zakaj vsi se moramo pokazati pred sodnim stolom Kristusovim, da prejme vsak po tem, kar je storil v telesu, bodisi dobro ali hudo.',
        11: 'Vedoč torej za strah Gospodov, prepričujemo ljudi, a Bogu smo razodeti; upam pa, da smo tudi v vaših vesteh razodeti.',
        12: 'Ne priporočamo vam zopet sami sebe, temuč vam dajemo priložnost, hvaliti se z nami, da imate kaj proti tem, kateri se z zunanjim hvalijo in ne s tem kar je v srcu.',
        13: 'Kajti ako smo predaleč stopili, se je zgodilo za Boga; ako smo zmerni, smo za vas.',
        14: 'Zakaj ljubezen Kristusova priganja nas, ki smo tako sodili: če je eden umrl za vse, so umrli vsi;',
        15: 'in za vse je umrl, da bi ti, kateri žive, nič več ne živeli zase, ampak za tega, ki je zanje umrl in je bil obujen.',
        16: 'Zatorej mi od sedaj nikogar ne poznamo po mesu; če smo pa tudi poznali po mesu Kristusa, ali sedaj ga več ne poznamo.',
        17: 'Zato če je kdo v Kristusu, je novo stvarjenje; staro je prešlo, glej, postalo je novo vse.',
        18: 'A vse to je iz Boga, ki nas je spravil s seboj po Kristusu in nam je dal službo sprave.',
        19: 'Bog je namreč bil v Kristusu in je svet spravil s seboj in jim ni zaračunil njih grehov, in poveril je nam besedo sprave.',
        20: 'Namesto Kristusa smo torej poslani, kakor da bi Bog opominjal po nas. Prosimo namesto Kristusa: Spravite se z Bogom!',
        21: 'Tega, ki ni poznal greha, je storil zaradi nas v greh, da bi postali mi pravičnost Božja v njem.',
    },
    6: {
        1: 'A kakor sodelavci Božji vas tudi opominjamo, da bi ne bili zaman prejeli milosti Božje –',
        2: 'govori namreč: „Ob času prijetnem sem te uslišal in v dan zveličanja sem ti pomogel“. Glej, sedaj je čas jako prijeten, glej, sedaj je dan zveličanja; –',
        3: 'nikomur v ničemer ne dajemo spotike, da se naši službi nič ne očita,',
        4: 'temuč v vsem se izkazujemo kakor Božje služabnike v mnogem potrpljenju, v stiskah, v potrebah, v težavah,',
        5: 'v udarcih, v ječah, v uporih, v trudih, v nespavanju, v postu;',
        6: 'v čistosti, v znanju, v prizanesljivosti, v dobrotljivosti, v svetem Duhu, v nehinavski ljubezni,',
        7: 'v besedi resnice, v moči Božji; z orožjem pravičnosti na desno in levo,',
        8: 'pri slavi in nečasti, na slabem in dobrem glasu, kakor zapeljivci, in vendar resnični,',
        9: 'kakor neznani, a dobro znani, kakor umirajoči, in glej, živimo, kakor kaznjeni, in vendar ne umorjeni,',
        10: 'kakor žalosteči se, a vedno se veselimo, kakor siromaki, a mnoge bogatimo, kakor ničesar neimajoči, pa imamo vse.',
        11: 'Naša usta so odprta k vam, Korinčani, srce naše je razširjeno.',
        12: 'Vam ni tesno v nas, ali vam je tesno v srcih vaših;',
        13: 'a da nam isto povrnete (kakor svojim otrokom govorim), razširite se tudi vi.',
        14: 'Ne vlecite tujega jarma z neverniki. Kako se namreč druži pravica s krivico? ali kakšno tovarištvo ima svetlost s temo?',
        15: 'Kakšno pa soglasje Kristusa z Belijalom? ali kakšen delež ima vernik z nevernikom?',
        16: 'A kakšna je zveza templja Božjega z maliki? Kajti mi smo tempelj Boga živega, kakor je rekel Bog: „Prebival bom v njih in med njimi bom hodil, in bodem njih Bog in oni bodo moje ljudstvo.',
        17: 'Zato odidite izmed njih in se ločite, govori Gospod, in nečistega se ne dotikujte, in jaz vas sprejmem,',
        18: 'in bodem vam Oče in vi bodete meni sinovi in hčere, pravi Gospod Vsemogočni“.',
    },
    7: {
        1: 'Ker imamo torej te obljube, ljubljeni, očistimo se vsakega madeža mesa in duha ter dopolnjujmo svetost v strahu Božjem!',
        2: 'Dajte nam mesta v srcu! Nikomur nismo storili krivice, nikogar nismo popačili, nikogar nismo prekanili.',
        3: 'Ne govorim tega v vašo obsodbo; saj sem poprej rekel, da ste v srcih naših, da bi radi z vami vred umrli in vkup živeli.',
        4: 'Velika je moja zaupljivost v govoru do vas, velika moja hvala o vas; napolnjen sem tolažbe, preobilo imam radosti ob vsej stiski naši.',
        5: 'Kajti tudi ko smo prišli v Macedonijo, ni imelo nič počitka meso naše, temuč z vseh strani smo bili stiskani: zunaj so bili boji, znotraj strah in bojazen.',
        6: 'Ali Bog, ki tolaži ponižne, nas je potolažil s prihodom Titovim;',
        7: 'toda ne samo s prihodom njegovim, ampak tudi s tolažbo, s katero se je on potolažil nad vami. Ko nam je pripovedoval vaše hrepenenje, vaš jok, vašo vnetost za mene, sem se tem bolj obveselil.',
        8: 'Zakaj čeprav sem vas razžalostil z listom, ni mi žal, dasi mi je žal bilo; vidim namreč, da vas je oni list res razžalostil, čeprav začasno.',
        9: 'Sedaj se radujem, ne da ste se razžalostili, temuč da ste se razžalostili na izpokorjenje; razžalostili ste se namreč Bogu po volji, da bi v ničemer ne imeli škode od nas.',
        10: 'Kajti žalost, ki je po volji Bogu, rodi izpokorjenje na zveličanje, ki se ga nikdar ni kesati; a žalost sveta rodi smrt.',
        11: 'Zakaj glejte, prav to, da ste se po volji Bogu razžalostili, kolikšno vam je obrodilo marljivost, pa zagovarjanje, pa nevoljo, pa strah, pa hrepenenje, pa gorečnost, pa maščevanje! V vsem ste se pokazali, da ste čisti v tej zadevi.',
        12: 'Torej čeprav sem vam pisal, sem pisal ne za voljo tistega, ki je storil krivico, tudi ne za voljo tistega, ki se mu je krivica storila, marveč da se pri vas pokaže marljivost vaša za nas v pričo Boga.',
        13: 'Zato smo bili potolaženi. V svoji tolažbi pa smo se še obilneje obveselili vsled radosti Titove, ker njegov duh je bil poživljen po vas vseh.',
        14: 'Ker ako sem se v čem njemu pohvalil z vami, nisem osramočen; ampak kakor smo vam vse v resnici govorili, tako se je tudi pohvala naša proti Titu izkazala resnična.',
        15: 'In srce njegovo vam je še bolj vdano, ko se spominja poslušnosti vseh vas, kako ste ga s strahom in trepetom sprejeli.',
        16: 'Vesel sem torej, da se smem v vsem zanašati na vas.',
    },
    8: {
        1: 'A na znanje vam, bratje, dajemo milost Božjo, ki je dana v cerkvah macedonskih,',
        2: 'da se je vkljub mnogim stiskam, v katerih so bili preizkušeni, obilost njih radosti in njih prevelika revščina povzpela do bogate radodarnosti.',
        3: 'Kajti po svoji moči, da, pričam, čez svojo moč so dali dobrovoljno,',
        4: 'z mnogo prošnjo nas proseč te milosti, da se smejo udeležiti službe za svete;',
        5: 'in ne samo to, kakor smo upali, marveč sebe so dali najprej Gospodu in nam po volji Božji;',
        6: 'tako da smo zaprosili Tita, da bi, kakor je prej započel, tako tudi dokončal pri vas tudi to milost.',
        7: 'Ali kakor ste v vsem bogati: v veri in besedi in spoznanju in vsaki marljivosti in svoji ljubezni do nas, bogati bodite tudi v tej milosti.',
        8: 'Ne govorim po zapovedi, temuč da po marljivosti drugih izkusim resničnost vaše ljubezni.',
        9: 'Kajti poznate milost Gospoda našega Jezusa Kristusa, da je, ko je bil bogat, zavoljo vas obubožal, da bi vi po njegovem uboštvu obogateli.',
        10: 'In v tem vam dajem svet: to je namreč na prid vam, ki ste prvi, od lani, započeli ne samo to delati, ampak tudi hoteti.',
        11: 'Sedaj pa dokončajte tudi dejanje; kakor je bila dobra volja hoteti, tako naj bode tudi izvršitev po tem, kar imate.',
        12: 'Kajti če je dobra volja, prijetna je po tem, kar kdo ima, ne po tem, česar nima.',
        13: 'Ne mislim namreč, da naj imajo drugi olajšavo, a vi stisko,',
        14: 'temuč po načelu enakosti: vaša obilost v sedanjem času naj služi za njih pomanjkanje, da bi tudi onih obilost služila za vaše pomanjkanje, da bode enakost;',
        15: 'kakor je pisano: „Kdor je mnogo nabral, ni imel preobilo, in kdor je malo, ni mu manjkalo.“',
        16: 'Hvala pa Bogu, ki je dal isto marljivost za vas v srce Titovo,',
        17: 'da je našo prošnjo sprejel, a ker je sam bil silno marljiv, je radovoljno odšel k vam.',
        18: 'Poslali pa smo ž njim vred brata, čigar hvala zaradi službe v evangeliju je po vseh cerkvah;',
        19: 'a ne samo to, ampak cerkve so ga tudi izvolile za sopotnika našega s tem milodarom, ki ga oskrbujemo za samega Gospoda slavo in v dokaz naše dobre volje;',
        20: 'ogibajoč se tega, da nam kdo kaj ne očita glede te bogate miloščine, ki jo oskrbujemo:',
        21: 'skrbimo namreč za poštenost ne samo pred Gospodom, ampak tudi pred ljudmi.',
        22: 'Poslali smo pa ž njima vred brata svojega, ki smo ga izkusili v mnogih stvareh mnogokrat, da je marljiv, sedaj pa da je mnogo marljivejši po mnogem zaupanju, ki ga ima do vas.',
        23: 'Kar se pa tiče Tita, on je moj tovariš in sodelavec za vas; kar se tiče naših bratov, ona sta poslanca cerkva, slava Kristusova.',
        24: 'Pokažite torej v pričo cerkva do njih dokaz svoje ljubezni in naše hvale z vami.',
    },
    9: {
        1: 'Kajti zastran službe, ki je za svete, mi ni treba pisati vam;',
        2: 'zakaj znana mi je vaša dobra volja, s katero se z vami hvalim Macedoncem, da je Ahaja pripravljena že od lani; in vaša gorečnost jih je prav mnogo izpodbodla.',
        3: 'A brate sem poslal, da ne bode hvala naša z vami zaman v tej zadevi, da bodete, kakor sem govoril, res pripravljeni,',
        4: 'da se, ako pridejo z menoj Macedonci in vas najdejo nepripravljene, kako ne osramotimo mi (da ne rečem, vi) v tem svojem zaupanju.',
        5: 'Potrebno se mi je torej zazdelo, poprositi brate, da bi šli pred mano k vam in prej pripravili vaš poprej obljubljeni blagoslov, da bode gotov, kakor resničen blagoslov in ne kakor skopost.',
        6: 'To pa pomnite: Kdor skopo seje, bo tudi skopo žel, in kdor seje bogato, bo tudi bogato žel.',
        7: 'Vsak naj da, kakor je v srcu namenil, ne z žalostjo ali po sili; kajti veselega dajalca ljubi Bog.',
        8: 'Bog pa more čez vas razliti obilo vsake milosti, da imate v vsem vsekdar vso obilost in ste bogati za vsako dobro delo,',
        9: 'kakor je pisano: „Razsipal je, dal je ubogim, njegova pravičnost ostane na vek.“',
        10: 'Ta pa, ki daje seme sejalcu in kruh za jed, vam dodeli in razmnoži setev vašo ter dá, da bodo rasli sadovi pravičnosti vaše,',
        11: 'da obogatite v vsem za vsako radodarnost, ki napravlja po nas zahvalo Bogu.',
        12: 'Kajti služba tega opravila ne dopolnjuje samo pomanjkanja svetih, ampak prinaša tudi po zahvalah od mnogih obilen sad Bogu;',
        13: 'ker po preizkušnji te službe hvalijo Boga za vaše pokorno pripoznanje evangelija Kristusovega in za vaše radodarno podeljevanje njim in vsem',
        14: 'ter molijo za vas tisti, ki hrepene po vas zavoljo premnoge milosti Božje v vas.',
        15: 'Hvala Bogu za njegov neizrečni dar!',
    },
    10: {
        1: 'Jaz Pavel sam pa vas opominjam po krotkosti in tihosti Kristusovi, ki sem vpričo vas resda ponižen med vami, a kadar me ni pri vas, pa drzen proti vam.',
        2: 'Prosim pa, da mi ne bo treba, kadar bodem pri vas, drzen biti s to zaupnostjo, s katero mislim, da se smem zdrzniti na nekatere, ki mislijo, kakor da živimo po mesu.',
        3: 'Kajti čeprav živimo v mesu, ne vojskujemo se po mesu',
        4: '(zakaj orožje našega vojskovanja ni meseno, ampak močno po Bogu za razrušenje trdnjav),',
        5: 'ko razdevamo sovražne naklepe in vsako visokost, ki se vzdiguje zoper spoznanje Božje, in vodimo vsako misel v sužnost pokorščine do Kristusa',
        6: 'in imamo pripravljeno maščevanje za vsako neposlušnost, kadar se izpolni vaša poslušnost.',
        7: 'Gledate li na to, kar je pred očmi? Če kdo zaupa sebi, da je Kristusov, pomisli naj zopet v sebi to: kakor je on Kristusov, prav tako smo tudi mi.',
        8: 'Kajti ko bi se tudi kaj obilneje hvalil z oblastjo našo, ki jo je nam dal Gospod za zidanje in ne za razdevanje vaše, ne bom se osramotil;',
        9: 'da se ne bo videlo, kakor da vas strašim z listi.',
        10: 'Kajti ‚listi njegovi‘, pravijo, ‚so tehtni in krepki, ali ko je navzočen s telesom, je slaboten in beseda mu je šibka‘.',
        11: 'To naj misli, kdor tako govori, da kakršni smo nenavzočni v besedi po listih, taki smo tudi navzočni v dejanju.',
        12: 'Kajti ne drznemo se pridružiti se k nekaterim ali primerjati se ž njimi, ki sami sebe priporočajo; kateri pa, ko se sami po sebi merijo in primerjajo sami sebe s seboj, ničesar ne umejo.',
        13: 'A mi se ne bomo čez vso mero hvalili, temuč po meri delokroga, ki nam ga je Bog podelil za mero, da naj dospemo tudi do vas.',
        14: 'Kajti mi se ne iztezamo predaleč, kakor da bi ne mogli doseči do vas, zakaj tudi prav do vas smo prišli v evangeliju Kristusovem;',
        15: 'in ne hvalimo se čez mero ali s tujimi trudi, temuč imamo upanje, da se, ker raste vera vaša, poveličamo med vami v soglasju z delokrogom svojim na še večjo obilnost,',
        16: 'tako da še onkraj vas oznanimo evangelij, ne da bi se hvalili s tem, kar je v delokrogu drugega že napravljenega.',
        17: 'Kdor se pa hvali, v Gospodu naj se hvali.',
        18: 'Kajti kdor sam sebe priporoča, ni preizkušen, ampak ta, kogar Gospod priporoča.',
    },
    11: {
        1: 'O, da bi me trpeli malo v moji nespameti! Pa saj me tudi potrpite.',
        2: 'Kajti vnet sem za vas z Božjo gorečnostjo, ker sem vas zaročil enemu možu, da vas privedem kot čisto devico Kristusu.',
        3: 'Bojim se pa, da se ne bi, kakor je kača Evo ukanila z zvijačo svojo, nekako tudi pokvarile misli vaše in se odvrnile od preprostosti in čistosti, ki je v srcu do Kristusa.',
        4: 'Kajti ko bi ta, ki prihaja, oznanjeval drugega Jezusa, ki ga mi nismo oznanili, ali ko bi prejemali drugega duha, ki ga niste prej prejeli, ali drugačen evangelij, ki ga niste sprejeli, lepo bi to trpeli.',
        5: 'Mislim namreč, da v ničemer nisem manjši od onih prevelikih apostolov.',
        6: 'Čeprav pa sem neuk v govoru, vendar nisem v znanju; ali v vsem smo znani pri vseh med vami.',
        7: 'Ali pa sem storil greh, sam sebe ponižujoč, da se vi povišate, ker sem vam brezplačno oznanil Božji evangelij?',
        8: 'Druge cerkve sem slekel, vzemši plačilo od njih, da morem služiti vam,',
        9: 'in ko sem bil pri vas in sem stradal, nisem bil nikomur nadležen. Kolikor mi je namreč manjkalo, so doložili bratje, ki so prišli od Macedonije; in v vsem sem se zdržal brez nadlege vam in se še zdržim.',
        10: 'Kakor je resnica Kristusova v meni, te hvale mi nihče ne vzame v krajih ahajskih.',
        11: 'Zakaj? ker vas ne ljubim? Bog ve.',
        12: 'Kar pa delam, še bom delal, da odvzamem priložnost tistim, ki priložnosti iščejo, da bi se, v čemer se hvalijo, pokazali take kakor tudi mi.',
        13: 'Kajti taki so krivi apostoli, ukanljivi delavci, izpreminjajoči se v apostole Kristusove.',
        14: 'In ni čuda, zakaj sam satan se izpreminja v angela svetlobe.',
        15: 'Ni torej nič velikega, če se tudi služabniki njegovi izpreminjajo v služabnike pravičnosti; katerih konec bode po njih delih.',
        16: 'Zopet pravim: Nihče naj ne misli, da sem nespameten. Če pa vendar mislite, pa me tudi sprejmite kakor nespametnega, da se nekoliko tudi jaz pohvalim.',
        17: 'Kar zdaj govorim, ne govorim po Gospodu, ampak kakor v nespameti, v svesti si, da se smem hvaliti.',
        18: 'Ko se mnogi hvalijo po mesu, naj se tudi jaz pohvalim.',
        19: 'Kajti radi prenašate nespametne, ko ste sami pametni.',
        20: 'Prenašate namreč, če vas kdo usužnuje, če vam kdo pojeda, če kdo jemlje, če se kdo povzdiguje, če vas kdo v lice bije.',
        21: 'Na sramoto priznavam: za to smo pa bili preslabi. V čemer je pa kdo drzen (po nespameti govorim), drzen sem tudi jaz.',
        22: 'Hebrejci so? Tudi jaz sem. Izraelci so? Tudi jaz sem. Seme Abrahamovo so? Tudi jaz sem.',
        23: 'Služabniki Kristusovi so? (Ne govorim po pameti:) Še bolj jaz: v trudih sem bil obilneje, v ječah obilneje, v udarcih neizmerneje, v smrti mnogokrat.',
        24: 'Od Judov sem jih dobil petkrat po štirideset brez ene,',
        25: 'trikrat so me šibali, enkrat kamenali, trikrat se je z menoj ladja razbila, noč in dan sem prebil sredi valov;',
        26: 'potoval sem mnogokrat, bil sem v nevarnostih od voda, v nevarnostih od razbojnikov, v nevarnostih od rojakov, v nevarnostih od poganov, v nevarnostih v mestu, v nevarnostih v puščavi, v nevarnostih na morju, v nevarnostih med krivimi brati:',
        27: 'v trudu in težavi, dostikrat v nespavanju, v lakoti in žeji, čestokrat v postu, v mrazu in goloti.',
        28: 'Razen tega, kar je zunanjega, je vsakdanji naval do mene, skrb za vse cerkve.',
        29: 'Kdo oslabi, da bi tudi jaz ne oslabel? Kdo se pohujšuje, da bi tudi mene ne skelelo?',
        30: 'Če se je treba hvaliti, hvalil se bom s tem, kar se tiče moje slabosti.',
        31: 'Bog in Oče Gospoda našega Jezusa, ki je hvaljen na veke, ve, da ne lažem.',
        32: 'V Damasku je dal namestnik kralja Areta zastražiti mesto Damaščanov, hoteč me ujeti;',
        33: 'pa skozi okno v košu so me po zidu spustili, in tako sem ubežal njegovim rokam.',
    },
    12: {
        1: 'Hvaliti se mi je treba, dasi nič ne koristi; pridem pa zdaj do prikazni in razodetij Gospodovih.',
        2: 'Poznam človeka v Kristusu, ki je bil pred štirinajstimi leti (ali v telesu, ne vem, ali izven telesa, ne vem; Bog ve), vzet tja v tretja nebesa.',
        3: 'In poznam takega človeka (ali v telesu, ali izven telesa, ne vem; Bog ve),',
        4: 'da je bil vzet v raj in je slišal neizrečne besede, katerih ne sme človek govoriti.',
        5: 'S takim se bom hvalil, sam s seboj se pa ne bom hvalil, razen s slabostmi svojimi.',
        6: 'Kajti ko bi se hotel pohvaliti, ne bi bil nespameten, ker bi govoril resnico; zdržim se pa, da ne bi kdo več o meni mislil, nego kar vidi na meni ali kar sliši od mene.',
        7: 'In zavoljo visokih razodetij, da bi se ne prevzel, mi je dan trn v meso, angel satanov, da me za uho bije, da se ne prevzamem.',
        8: 'Zavoljo tega sem trikrat prosil Gospoda, da bi odstopil od mene,',
        9: 'a dejal mi je: Dosti ti je moja milost; zakaj moč moja se v slabosti izkazuje popolna. Torej se bom najrajši hvalil s slabostmi svojimi, da se ušatori nad mano moč Kristusova.',
        10: 'Zato sem dobre volje v slabostih, v zasramovanju, v potrebah, v preganjanju, v težavah, za Kristusa; zakaj kadar sem slab, tedaj sem močan.',
        11: 'Postal sem nespameten, hvaleč se; vi ste me prisilili. Kajti mene bi bili morali vi hvaliti, ker nisem bil nič manjši od onih prevelikih apostolov, čeprav nisem nič.',
        12: 'Saj so se znamenja apostola godila med vami v vsem potrpljenju, v znamenjih in čudežih in močeh.',
        13: 'Kaj namreč je, v čemer ste bili prikrajšani nasproti drugim cerkvam, razen le, da vas jaz sam nisem nadlegoval? Odpustite mi to krivico!',
        14: 'Glej, tretjič sem pripravljen priti k vam in ne bom vas nadlegoval; kajti ne iščem, kar je vašega, marveč vas. Niso namreč otroci dolžni roditeljem zakladov zbirati, ampak roditelji otrokom.',
        15: 'A jaz prav rad potrošim vse in sebe žrtvujem za duše vaše. Če vas obilneje ljubim, me li tem manj ljubite?',
        16: 'Ali naj bo, jaz vam nisem bil nadležen; toda ‚zvit človek sem vas z zvijačo pridobil‘.',
        17: 'Sem li vas mar opeharil po katerem teh, ki sem jih k vam poslal?',
        18: 'Naprosil sem Tita in ž njim poslal brata: ali vas je mar Tit opeharil? Nismo li v enem Duhu hodili? ne po enih stopinjah?',
        19: 'Ves ta čas mislite, da se vam zagovarjamo. Pred Bogom v Kristusu govorimo, a vse to, ljubljeni, da pospešimo vaš napredek.',
        20: 'Kajti bojim se, da vas morda, kadar pridem, ne najdem takih, kakršne hočem, in da mene najdete takega, kakršnega nočete; da morda bodo med vami prepiri, zavist, srd, svade, opravljanje, prišeptavanje, hujskanje, neredi;',
        21: 'da me, ko zopet pridem, poniža Bog moj pri vas in da se bom žalostil zaradi mnogih, ki so prej grešili in se niso kesali za nečistost in nesramnost in pohotnost, ki so jo počeli.',
    },
    13: {
        1: 'Sedaj grem tretjič k vam. Na tem, kar povesta dve priči ali tri, bo stala vsaka beseda.',
        2: 'Prej sem povedal in prej pravim, kakor drugič navzočen in sedaj nenavzočen, tem, kateri so prej grešili, in vsem drugim: kadar pridem zopet, ne bom prizanašal;',
        3: 'ker iščete dokaza, da v meni govori Kristus, ki za vas ni slaboten, temuč je močan med vami.',
        4: 'Kajti čeprav je bil na križ razpet po slabosti, vendar živi po moči Božji. In tako smo tudi mi slabotni v njem, ali živeli bomo ž njim po moči Božji za vas.',
        5: 'Sami sebe izkušajte, če ste v veri, sami sebe ogledujte! Ali pa ne poznate sami sebe, da je Jezus Kristus v vas? razen če ste morda odvrženi.',
        6: 'Upam pa, da boste spoznali, da mi nismo odvrženi.',
        7: 'Molimo pa k Bogu, da ne storite nič hudega, ne da se mi pokažemo preizkušene, ampak da vi dobro delate, čeprav bomo mi kakor odvrženi.',
        8: 'Kajti ničesar ne moremo zoper resnico, ampak vse za resnico.',
        9: 'Veselimo se namreč, kadar smo mi slabotni, a vi močni; da, zato tudi molimo: za vašo popolnost.',
        10: 'Zato pišem to nenavzočen, da mi v navzočnosti ne bo treba biti ostremu po oblasti, ki mi jo je dal Gospod na zidanje in ne na razdevanje.',
        11: 'Sicer se pa, bratje, radujte, bodite popolni, tolažite se, ene misli bodite, v miru živite; in Bog ljubezni in miru bode z vami.',
        12: 'Pozdravite drug drugega v svetem poljubu!',
        13: 'Pozdravljajo vas vsi sveti.',
        14: 'Milost Gospoda Jezusa Kristusa in ljubezen Božja in deleštvo svetega Duha z vsemi vami!',
    },
}
